// ============================================================================
// WF-22 · סיווג המוצר וניתוב לתהליך המקצועי הנכון
// ============================================================================
// הראוטר לא מבצע שום כתיבה. תפקידו היחיד: להחליט לאיזה תהליך להעביר,
// ולהעשיר את ה-payload בקטגוריה של המוצר.
// ============================================================================

// ==== LOGIC (pure) ====
const ROUTES = {
  BOOST:     '/webhook/pro-boost-roital',
  MENTORING: '/webhook/pro-mentoring-roital',
  CONTINUE:  '/webhook/pro-continue-roital',
};
const BOOST_PRODUCT_IDS = ['2F73403A-20DE-47A7-B0CB-DF4761B45F21'];
const N8N_BASE = 'https://n8n.srv964196.hstgr.cloud';

function LOGIC(ctx) {
  const S = (v) => (v === undefined || v === null) ? '' : String(v).trim();
  const U = (v) => S(v).toUpperCase();
  const raw = ctx.raw || {};
  const d = (raw && raw.body && typeof raw.body === 'object') ? raw.body : raw;
  const products = (ctx.productResp && Array.isArray(ctx.productResp.data)) ? ctx.productResp.data : [];

  const productId = U(d.productId);
  const product = products.find((p) => U(p.productid) === productId) || null;
  const cat = product && product.categorycode !== null && product.categorycode !== undefined
    ? parseInt(product.categorycode, 10) : null;

  let branch = null; const why = [];
  if (productId && BOOST_PRODUCT_IDS.map(U).indexOf(productId) !== -1) {
    branch = 'BOOST'; why.push('מזהה המוצר הוא סדנת הבוסט.');
  } else if (cat === 101) { branch = 'MENTORING'; why.push('קטגוריה ראשית 101 — תוכנית ליווי.'); }
  else if (cat === 102) { branch = 'CONTINUE'; why.push('קטגוריה ראשית 102 — תוכנית המשך.'); }
  else if (cat === 100) { why.push('קטגוריה 100 שאינה סדנת הבוסט — אין תהליך מקצועי מוגדר.'); }
  else { why.push('לא נמצא מוצר תואם בקטלוג — לא ניתן לסווג.'); }

  const IDLE = { url: N8N_BASE + '/webhook/pro-noop-roital', route: null };
  if (!branch) {
    return [{ json: { routed: false, branch: null, reasons: why,
      productId, productName: S(d.productName) || (product ? S(product.name) : ''),
      categoryCode: cat, targetUrl: '', payload: {}, _skip: true } }];
  }
  const payload = Object.assign({}, d, {
    categoryCode: cat,
    productName: S(d.productName) || (product ? S(product.name) : ''),
  });
  return [{ json: { routed: true, branch, reasons: why, productId,
    productName: payload.productName, categoryCode: cat,
    targetUrl: N8N_BASE + ROUTES[branch], payload, _skip: false } }];
}

// ==== N8N BINDING ====
return LOGIC({ raw: $('Webhook · סיום תשלום').first().json, productResp: $input.first().json });
